INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5810, 'CIRI SAMPUL: PPPK (ISIAN OTOMATIS dari panel; kosong = tidak berlaku; contoh isi: [&#9679; PPPK T])', 'data_teks', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5810);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5811, 'CIRI SAMPUL: TNI (ISIAN OTOMATIS dari panel; kosong = tidak berlaku; contoh isi: [&#9679; TNI T])', 'data_teks', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5811);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5812, 'CIRI SAMPUL: POLRI (ISIAN OTOMATIS dari panel; kosong = tidak berlaku; contoh isi: [&#9679; POLRI T])', 'data_teks', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5812);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5813, 'CIRI SAMPUL: BUMN/BUMD (ISIAN OTOMATIS dari panel; kosong = tidak berlaku; contoh isi: [&#9679; BUMN/BUMD T])', 'data_teks', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5813);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5814, 'CIRI SAMPUL: DISABILITAS (OTOMATIS; sisi P/T; kosong = tidak berlaku)', 'data_sql', 'SELECT (CASE WHEN x.a AND x.b THEN ''[&#9679; DISABILITAS P+T]'' WHEN x.a THEN ''[&#9679; DISABILITAS P]'' WHEN x.b THEN ''[&#9679; DISABILITAS T]'' ELSE '''' END) AS data FROM (SELECT EXISTS(SELECT 1 FROM perkara_pihak1 k JOIN pihak h ON h.id=k.pihak_id WHERE k.perkara_id=#perkara_id# AND h.difabel=''Y'') AS a, EXISTS(SELECT 1 FROM perkara_pihak2 k JOIN pihak h ON h.id=k.pihak_id WHERE k.perkara_id=#perkara_id# AND h.difabel=''Y'') AS b) x', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5814);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5815, 'CIRI SAMPUL: PENERJEMAH (ISIAN TANGAN; isi [&#9679; PENERJEMAH] bila perlu penerjemah/juru bahasa; kosong = tidak ada)', 'data_teks', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5815);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5816, 'CIRI SAMPUL: WNA (OTOMATIS; sisi P/T; kosong = tidak berlaku)', 'data_sql', 'SELECT (CASE WHEN x.a AND x.b THEN ''[&#9679; WNA P+T]'' WHEN x.a THEN ''[&#9679; WNA P]'' WHEN x.b THEN ''[&#9679; WNA T]'' ELSE '''' END) AS data FROM (SELECT EXISTS(SELECT 1 FROM perkara_pihak1 k JOIN pihak h ON h.id=k.pihak_id WHERE k.perkara_id=#perkara_id# AND IFNULL(h.warga_negara_id,1)<>1) AS a, EXISTS(SELECT 1 FROM perkara_pihak2 k JOIN pihak h ON h.id=k.pihak_id WHERE k.perkara_id=#perkara_id# AND IFNULL(h.warga_negara_id,1)<>1) AS b) x', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5816);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5817, 'CIRI SAMPUL: VERSTEK (OTOMATIS; kosong = tidak berlaku)', 'data_sql', 'SELECT IF(IFNULL((SELECT putusan_verstek FROM perkara_putusan WHERE perkara_id=#perkara_id# LIMIT 1),'''') IN (''Y'',''1''),''[&#9650; VERSTEK]'','''') AS data', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5817);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5818, 'CIRI SAMPUL: KUMULASI (OTOMATIS dari perkara_kumulasi; kosong = tidak ada)', 'data_sql', 'SELECT IF(COUNT(*)>0,CONCAT(''[&#9650; KUMULASI '',COUNT(*),'']''),'''') AS data FROM perkara_kumulasi WHERE perkara_id=#perkara_id#', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5818);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5819, 'CIRI SAMPUL: REKONVENSI (ISIAN OTOMATIS dari panel; kosong = tidak berlaku)', 'data_teks', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5819);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5820, 'CIRI SAMPUL: MEDIASI (OTOMATIS; kosong = tidak berlaku)', 'data_sql', 'SELECT IF(EXISTS(SELECT 1 FROM perkara_mediasi WHERE perkara_id=#perkara_id# AND penetapan_penunjukan_mediator IS NOT NULL),''[&#9650; MEDIASI]'','''') AS data', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5820);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5821, 'CIRI SAMPUL: SITA (OTOMATIS; kosong = tidak berlaku)', 'data_sql', 'SELECT IF(EXISTS(SELECT 1 FROM perkara_proses WHERE perkara_id=#perkara_id# AND proses_nama LIKE ''%sita%''),''[&#9650; SITA]'','''') AS data', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5821);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5822, 'CIRI SAMPUL: SIDANG KELILING (OTOMATIS; kosong = tidak berlaku)', 'data_sql', 'SELECT IF(EXISTS(SELECT 1 FROM perkara_jadwal_sidang WHERE perkara_id=#perkara_id# AND sidang_keliling=''Y''),''[&#9650; SIDANG KELILING]'','''') AS data', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5822);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5823, 'CIRI SAMPUL: HAKIM TUNGGAL (OTOMATIS; kosong = tidak berlaku)', 'data_sql', 'SELECT IF((SELECT COUNT(*) FROM perkara_hakim_pn WHERE perkara_id=#perkara_id# AND aktif=''Y'')=1,''[&#9650; HAKIM TUNGGAL]'','''') AS data', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5823);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5824, 'CIRI SAMPUL: GUGATAN SEDERHANA (OTOMATIS; kosong = tidak berlaku)', 'data_sql', 'SELECT IF(IFNULL((SELECT alur_perkara_id FROM perkara WHERE perkara_id=#perkara_id#),0)=17,''[&#9650; GUGATAN SEDERHANA]'','''') AS data', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5824);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5825, 'CIRI SAMPUL: VERZET (OTOMATIS; kosong = tidak berlaku)', 'data_sql', 'SELECT IF(EXISTS(SELECT 1 FROM perkara_jadwal_sidang WHERE perkara_id=#perkara_id# AND verzet=''Y''),''[&#9650; VERZET]'','''') AS data', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5825);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5826, 'CIRI SAMPUL: DISPENSASI KAWIN (OTOMATIS; kosong = tidak berlaku)', 'data_sql', 'SELECT IF(IFNULL((SELECT jenis_perkara_id FROM perkara WHERE perkara_id=#perkara_id#),0)=362,''[&#9650; DISPENSASI KAWIN]'','''') AS data', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5826);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5827, 'CIRI SAMPUL: IKRAR TALAK (OTOMATIS; kosong = tidak berlaku)', 'data_sql', 'SELECT IF(EXISTS(SELECT 1 FROM perkara_ikrar_talak WHERE perkara_id=#perkara_id#),''[&#9650; IKRAR TALAK]'','''') AS data', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5827);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5801, 'CIRI PERKARA SAMPUL (OTOMATIS: gabungan 5802 sampai 5827; kosong semua = tidak ada ciri khusus)', 'data_sql', 'SELECT IFNULL(NULLIF(TRIM(CONCAT_WS(''  '',NULLIF(''#5802#'',''''),NULLIF(''#5803#'',''''),NULLIF(''#5805#'',''''),NULLIF(''#5806#'',''''),NULLIF(''#5807#'',''''),NULLIF(''#5808#'',''''),NULLIF(''#5809#'',''''),NULLIF(''#5810#'',''''),NULLIF(''#5811#'',''''),NULLIF(''#5812#'',''''),NULLIF(''#5813#'',''''),NULLIF(''#5814#'',''''),NULLIF(''#5815#'',''''),NULLIF(''#5816#'',''''),NULLIF(''#5817#'',''''),NULLIF(''#5818#'',''''),NULLIF(''#5819#'',''''),NULLIF(''#5820#'',''''),NULLIF(''#5821#'',''''),NULLIF(''#5822#'',''''),NULLIF(''#5823#'',''''),NULLIF(''#5824#'',''''),NULLIF(''#5825#'',''''),NULLIF(''#5826#'',''''),NULLIF(''#5827#'',''''))),''''),''- tidak ada ciri khusus -'') AS data', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5801);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5800, 'JENIS PERKARA SAMPUL (OTOMATIS: jenis perkara + kumulasi)', 'data_sql', 'SELECT CONCAT(''#0048#'',IFNULL((SELECT CONCAT('' Kumulasi '',REPLACE(GROUP_CONCAT(j.nama SEPARATOR ''|''),''|'','' dan '')) FROM perkara_kumulasi k JOIN jenis_perkara j ON j.id=k.jenis_perkara_id WHERE k.perkara_id=#perkara_id# HAVING COUNT(*)>0),'''')) AS data', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5800);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5829, 'BARIS IKRAR TALAK SAMPUL (OTOMATIS; kosong bila bukan cerai talak)', 'data_sql', 'SELECT IFNULL((SELECT CONCAT(''<b>IKRAR TALAK</b>  PMH '',IFNULL(CONCAT(DAY(i.penetapan_majelis_hakim),'' '',ELT(MONTH(i.penetapan_majelis_hakim),''Januari'',''Februari'',''Maret'',''April'',''Mei'',''Juni'',''Juli'',''Agustus'',''September'',''Oktober'',''November'',''Desember''),'' '',YEAR(i.penetapan_majelis_hakim)),''-''),''  -  PHS ikrar '',IFNULL(CONCAT(DAY(i.tanggal_penetapan_sidang_ikrar),'' '',ELT(MONTH(i.tanggal_penetapan_sidang_ikrar),''Januari'',''Februari'',''Maret'',''April'',''Mei'',''Juni'',''Juli'',''Agustus'',''September'',''Oktober'',''November'',''Desember''),'' '',YEAR(i.tanggal_penetapan_sidang_ikrar)),''-''),''  -  Sidang ikrar '',IFNULL(CONCAT(DAY(i.tgl_ikrar_talak),'' '',ELT(MONTH(i.tgl_ikrar_talak),''Januari'',''Februari'',''Maret'',''April'',''Mei'',''Juni'',''Juli'',''Agustus'',''September'',''Oktober'',''November'',''Desember''),'' '',YEAR(i.tgl_ikrar_talak)),''-'')) FROM perkara_ikrar_talak i WHERE i.perkara_id=#perkara_id# LIMIT 1),'''') AS data', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5829);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5836, 'MEDIATOR SAMPUL (OTOMATIS dari mediasi terakhir)', 'data_sql', 'SELECT m.mediator_text AS data FROM perkara_mediasi m WHERE m.perkara_id=#perkara_id# ORDER BY m.mediasi_id DESC LIMIT 1', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5836);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5837, 'HASIL MEDIASI SAMPUL (OTOMATIS; kosong bila belum ada hasil)', 'data_sql', 'SELECT (CASE WHEN m.mediasi_berhasil IN (''Y'',''1'') THEN ''Berhasil'' WHEN m.mediasi_gagal IN (''Y'',''1'') THEN ''Tidak berhasil'' ELSE '''' END) AS data FROM perkara_mediasi m WHERE m.perkara_id=#perkara_id# ORDER BY m.mediasi_id DESC LIMIT 1', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5837);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5839, 'KONSEPTOR SAMPUL (ISIAN TANGAN)', 'data_teks', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5839);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5840, 'TGL PEMBERITAHUAN PUTUSAN / PBT (OTOMATIS: terakhir)', 'data_sql', 'SELECT MAX(tanggal_pemberitahuan_putusan) AS data FROM perkara_putusan_pemberitahuan_putusan WHERE perkara_id=#perkara_id#', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5840);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5841, 'SEBUTAN PIHAK I SAMPUL (OTOMATIS menurut jenis perkara; selain yang dikhususkan = #8146#)', 'data_sql', 'SELECT (CASE p.jenis_perkara_id WHEN 362 THEN ''PEMOHON (ORANG TUA / WALI)'' WHEN 360 THEN ''PEMOHON I'' WHEN 363 THEN ''PEMOHON (CALON MEMPELAI)'' WHEN 354 THEN ''PEMOHON (CALON WALI)'' WHEN 371 THEN ''PEMOHON (AHLI WARIS)'' ELSE ''#8146#'' END) AS data FROM perkara p WHERE p.perkara_id=#perkara_id#', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5841);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5845, 'FOKUS SAMPUL (ISIAN TANGAN; dipakai bila jenis perkara belum punya kueri otomatis: nama anak, calon mempelai, pewaris, dan seterusnya)', 'data_teks', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5845);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5846, 'POKOK PERKARA SAMPUL (ISIAN TANGAN; baris dipisah <br>, dipakai bila jenis perkara belum punya kueri otomatis)', 'data_teks', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5846);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5842, 'FOKUS PERKARA SAMPUL (OTOMATIS: dispensasi kawin = anak yang dimohonkan; itsbat nikah = pasangan; asal usul anak = anak; lainnya = isian 5845)', 'data_sql', 'SELECT (CASE p.jenis_perkara_id WHEN 362 THEN CONCAT(''<b>ANAK YANG DIMOHONKAN DISPENSASI</b><br>'', IFNULL((SELECT IF(CAST(IFNULL(u.data,''99'') AS UNSIGNED)<19 OR IFNULL(w.data,'''')='''', n.data, w.data) FROM aps_badilag.abt_data_teks n LEFT JOIN aps_badilag.abt_data_teks u ON u.no_var=601 AND u.perkara_id=n.perkara_id LEFT JOIN aps_badilag.abt_data_teks w ON w.no_var=606 AND w.perkara_id=n.perkara_id WHERE n.no_var=600 AND n.perkara_id=p.perkara_id), '''')) WHEN 360 THEN CONCAT(''<b>PASANGAN YANG DIITSBATKAN</b><br>'', IFNULL((SELECT GROUP_CONCAT(k.nama ORDER BY k.urutan SEPARATOR '' dan '') FROM perkara_pihak1 k WHERE k.perkara_id=p.perkara_id AND k.urutan<=2), '''')) WHEN 358 THEN CONCAT(''<b>ANAK YANG DIMOHONKAN ASAL USULNYA</b><br>'', IFNULL((SELECT a.nama_anak FROM perkara_anak_pihak a WHERE a.perkara_id=p.perkara_id ORDER BY a.id LIMIT 1), '''')) ELSE IFNULL((SELECT TRIM(data) FROM aps_badilag.abt_data_teks WHERE no_var=5845 AND perkara_id=p.perkara_id), '''') END) AS data FROM perkara p WHERE p.perkara_id=#perkara_id#', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5842);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5843, 'POKOK PERKARA SAMPUL (OTOMATIS menurut jenis: cerai = pernikahan dan anak; itsbat = tanggal/tempat/alasan; dispensasi = alasan; lainnya = isian 5846)', 'data_sql', 'SELECT (CASE WHEN p.jenis_perkara_id IN (346,347) THEN CONCAT(''<b>PERNIKAHAN DAN ANAK</b><br>Tanggal nikah: '', IFNULL(CONCAT(DAY(n.tgl_nikah),'' '',ELT(MONTH(n.tgl_nikah),''Januari'',''Februari'',''Maret'',''April'',''Mei'',''Juni'',''Juli'',''Agustus'',''September'',''Oktober'',''November'',''Desember''),'' '',YEAR(n.tgl_nikah)),''-''), ''<br>KUA: '', IFNULL(n.kua_tempat_nikah,''-''), ''<br>Anak: '', (SELECT COUNT(*) FROM perkara_anak_pihak a WHERE a.perkara_id=p.perkara_id), '' orang'') WHEN p.jenis_perkara_id=360 THEN CONCAT(''<b>PERNIKAHAN YANG DIITSBATKAN</b><br>Tanggal menikah: '', IFNULL(CONCAT(DAY(i.tgl_menikah),'' '',ELT(MONTH(i.tgl_menikah),''Januari'',''Februari'',''Maret'',''April'',''Mei'',''Juni'',''Juli'',''Agustus'',''September'',''Oktober'',''November'',''Desember''),'' '',YEAR(i.tgl_menikah)),''-''), ''<br>Tempat menikah: '', IFNULL(i.tempat_menikah,''-''), ''<br>Alasan: '', IFNULL((SELECT GROUP_CONCAT(l.nama SEPARATOR ''; '') FROM perkara_alasan_nikah l WHERE l.perkara_id=p.perkara_id),''-'')) WHEN p.jenis_perkara_id=362 THEN CONCAT(''<b>ANAK DAN CALON PASANGAN</b><br>Alasan dispensasi: '', IFNULL((SELECT GROUP_CONCAT(l.nama SEPARATOR ''; '') FROM perkara_alasan_nikah l WHERE l.perkara_id=p.perkara_id),''-'')) ELSE IFNULL((SELECT TRIM(data) FROM aps_badilag.abt_data_teks WHERE no_var=5846 AND perkara_id=p.perkara_id), '''') END) AS data FROM perkara p LEFT JOIN perkara_data_pernikahan n ON n.perkara_id=p.perkara_id LEFT JOIN perkara_data_itsbat i ON i.perkara_id=p.perkara_id WHERE p.perkara_id=#perkara_id#', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5843);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5851, 'DAFTAR ISI BUNDEL A: NO (OTOMATIS; satu baris per dokumen yang ada)', 'data_sql', 'SELECT aps_badilag.isian_rtf_daftar_isi(#perkara_id#,''A'',1) AS data', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5851);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5852, 'DAFTAR ISI BUNDEL A: JENIS DOKUMEN (OTOMATIS; satu baris per dokumen yang ada)', 'data_sql', 'SELECT aps_badilag.isian_rtf_daftar_isi(#perkara_id#,''A'',2) AS data', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5852);
INSERT INTO abt_variabel (no_var, nama, data_type, sql_query, locked) SELECT 5853, 'DAFTAR ISI BUNDEL A: TANGGAL (OTOMATIS; satu baris per dokumen yang ada)', 'data_sql', 'SELECT aps_badilag.isian_rtf_daftar_isi(#perkara_id#,''A'',3) AS data', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM abt_variabel WHERE no_var = 5853);
